function reverseStretch(head: ListNode | null, left: number, right: number): ListNode | null {
  const vals: number[] = [];
  for (let n = head; n; n = n.next) vals.push(n.val);
  for (let i = left - 1, j = right - 1; i < j; i++, j--) [vals[i], vals[j]] = [vals[j], vals[i]];
  let k = 0;
  for (let n = head; n; n = n.next) n.val = vals[k++];
  return head;
}

