class Solution:
    def reverseStretch(self, head: Optional[ListNode], left: int, right: int) -> Optional[ListNode]:
        vals, n = [], head
        while n:
            vals.append(n.val)
            n = n.next
        vals[left - 1:right] = vals[left - 1:right][::-1]
        n, k = head, 0
        while n:
            n.val = vals[k]
            n, k = n.next, k + 1
        return head

