function reverseStretch(head: ListNode | null, left: number, right: number): ListNode | null {
  const dummy = new ListNode(0, head);
  let prev: ListNode = dummy;
  for (let i = 1; i < left; i++) prev = prev.next!;
  const cur = prev.next!; // ends up as the last node of the stretch
  for (let i = 0; i < right - left; i++) {
    const move = cur.next!;
    cur.next = move.next;
    move.next = prev.next;
    prev.next = move;
  }
  return dummy.next;
}

